if($username===''){http_response_code(400);$username='User PPPoE';}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PPPoE User - <?=htmlspecialchars($username,ENT_QUOTES,'UTF-8')?> - NetMonitor</title><link rel="stylesheet" href="../assets/css/variables.css?v=8"><link rel="stylesheet" href="../assets/css/common.css?v=8"><link rel="stylesheet" href="../assets/css/theme.css?v=1"><link rel="stylesheet" href="../assets/css/pppoe.css?v=15"><style>body{margin:0}.user-page{max-width:1120px;margin:0 auto;padding:22px}.head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:16px}.title{margin:0;color:var(--text);font-size:23px;font-weight:800}.sub{margin-top:4px;color:var(--muted);font-size:11px}.actions{display:flex;gap:7px;flex-wrap:wrap}.btnx{display:inline-flex;align-items:center;text-decoration:none;border:1px solid var(--border);background:var(--card);color:var(--text);border-radius:8px;padding:8px 12px;font-size:11px;font-weight:700}.btnx.primary{background:var(--primary);color:#fff;border-color:var(--primary)}.card{background:var(--card);border:1px solid var(--border);border-radius:14px;box-shadow:var(--shadow-card,0 2px 10px rgba(0,0,0,.04));padding:15px;margin-bottom:12px}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px}.info{border:1px solid var(--border);border-radius:10px;padding:11px}.info span{display:block;color:var(--muted);font-size:8px;text-transform:uppercase;margin-bottom:4px}.info b{color:var(--text);font-size:14px;word-break:break-word}.live{display:inline-flex;align-items:center;gap:6px;font-size:10px;color:#059669;font-weight:700}.dot{width:7px;height:7px;border-radius:50%;background:#10b981}.offline{color:#dc3545}.traffic{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px}.traffic .box{border:1px solid var(--border);border-radius:10px;padding:12px}.traffic b{display:block;color:var(--text);font-size:18px}.traffic span{color:var(--muted);font-size:8px}.chart-title{font-size:12px;font-weight:750;color:var(--text);margin-bottom:8px}.chart-wrap{height:280px}.chart{width:100%;height:100%;display:block}.status{margin-left:7px}.error{color:#dc3545;font-size:10px}.note{color:var(--muted);font-size:9px;margin-top:8px}@media(max-width:850px){.grid,.traffic{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.user-page{padding:12px}.head{align-items:flex-start;flex-direction:column}.grid,.traffic{grid-template-columns:1fr}.chart-wrap{height:230px}}</style></head><body><main class="user-page"><header class="head"><div><h1 class="title">PPPoE User — <?=htmlspecialchars($username,ENT_QUOTES,'UTF-8')?></h1><div class="sub"><span id="status" class="live"><i class="dot"></i>Memuat status...</span></div></div><div class="actions"><a class="btnx" href="./">← PPPoE</a><a class="btnx primary" href="history.php?username=<?=rawurlencode($username)?>">Traffic History</a></div></header><section class="card"><div class="grid"><div class="info"><span>Username</span><b id="name">-</b></div><div class="info"><span>IP Address</span><b id="ip">-</b></div><div class="info"><span>Profile</span><b id="profile">-</b></div><div class="info"><span>Service</span><b id="service">-</b></div><div class="info"><span>Caller ID / MAC</span><b id="caller">-</b></div><div class="info"><span>Interface</span><b id="iface">-</b></div><div class="info"><span>Uptime</span><b id="uptime">-</b></div><div class="info"><span>Session ID</span><b id="session">-</b></div></div></section><section class="card"><div class="chart-title">Live Traffic <span class="status" id="updated">-</span></div><div class="traffic"><div class="box"><b id="rx">0 B</b><span>RX TOTAL</span></div><div class="box"><b id="tx">0 B</b><span>TX TOTAL</span></div><div class="box"><b id="rxRate">0 B/s</b><span>DOWNLOAD LIVE</span></div><div class="box"><b id="txRate">0 B/s</b><span>UPLOAD LIVE</span></div></div><div class="note">Kecepatan dihitung dari perubahan counter antar polling.</div></section><section class="card"><div class="chart-title">Traffic History — 24 Jam</div><div class="chart-wrap"><canvas id="chart" class="chart"></canvas></div><div id="chartMsg" class="note"></div></section></main><script>const USER=<?=json_encode($username,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>,statsApi='../api/pppoe_stats.php',histApi='../api/pppoe_history.php';const $=id=>document.getElementById(id);let oldRx=0,oldTx=0,oldAt=0;function bytes(n){n=Number(n)||0;if(n<1024)return n.toFixed(0)+' B';const u=['KB','MB','GB','TB'];let i=-1;do{n/=1024;i++}while(n>=1024&&i<u.length-1);return n.toFixed(n>=100?0:1)+' '+u[i]}function rate(n){return bytes(n)+'/s'}function draw(d){const c=$('chart'),r=c.getBoundingClientRect(),q=devicePixelRatio||1,w=Math.max(320,r.width),h=Math.max(180,r.height);c.width=w*q;c.height=h*q;const x=c.getContext('2d');x.scale(q,q);x.clearRect(0,0,w,h);const vals=[...(d.rx||[]),...(d.tx||[])].map(Number),max=Math.max(...vals,1),L=52,R=18,T=16,B=30,pw=w-L-R,ph=h-T-B,s=getComputedStyle(document.body),mut=s.getPropertyValue('--muted')||'#64748b',bd=s.getPropertyValue('--border')||'#e2e8f0',pr=s.getPropertyValue('--primary')||'#2563eb';x.font='9px sans-serif';x.fillStyle=mut;x.strokeStyle=bd;for(let i=0;i<=4;i++){let y=T+ph*i/4;x.beginPath();x.moveTo(L,y);x.lineTo(L+pw,y);x.stroke();x.fillText(bytes(max*(1-i/4)),4,y+3)}function line(a,dash){if(!a.length)return;x.beginPath();a.forEach((v,i)=>{let px=L+(a.length<2?0:pw*i/(a.length-1)),py=T+ph-(Number(v)/max)*ph;i?x.lineTo(px,py):x.moveTo(px,py)});x.strokeStyle=pr;x.lineWidth=2;x.setLineDash(dash?[5,4]:[]);x.stroke();x.setLineDash([])}line(d.rx||[],false);line(d.tx||[],true);x.fillStyle=mut;x.fillText('RX —',L,h-8);x.fillText('TX - -',L+48,h-8);if(d.labels?.length){x.fillText(d.labels[0],L,h-19);x.fillText(d.labels[d.labels.length-1],Math.max(L,w-95),h-19)}}async function refresh(){try{const r=await fetch(statsApi+'?t='+Date.now(),{cache:'no-store'}),d=await r.json();if(!r.ok||!d.success)throw Error(d.message||'Gagal mengambil status');const u=(d.active||[]).find(x=>String(x.name).toLowerCase()===USER.toLowerCase());if(!u){$('status').innerHTML='<i class="dot" style="background:#dc3545"></i>OFFLINE';$('status').classList.add('offline');return}$('status').innerHTML='<i class="dot"></i>ONLINE';$('name').textContent=u.name||USER;$('ip').textContent=u.address||'-';$('profile').textContent=u.profile||'-';$('service').textContent=u.service||'-';$('caller').textContent=u.caller_id||'-';$('iface').textContent=u.interface||'-';$('uptime').textContent=u.uptime||'-';$('session').textContent=u.session_id||'-';$('rx').textContent=bytes(u.bytes_in);$('tx').textContent=bytes(u.bytes_out);const now=Date.now(),dt=oldAt?(now-oldAt)/1000:0;$('rxRate').textContent=rate(dt>0?Math.max(0,(Number(u.bytes_in)||0)-oldRx)/dt:0);$('txRate').textContent=rate(dt>0?Math.max(0,(Number(u.bytes_out)||0)-oldTx)/dt:0);oldRx=Number(u.bytes_in)||0;oldTx=Number(u.bytes_out)||0;oldAt=now;$('updated').textContent='• update '+new Date().toLocaleTimeString('id-ID')}catch(e){$('status').textContent=e.message}}async function history(){try{const r=await fetch(histApi+'?username='+encodeURIComponent(USER)+'&range=24h&t='+Date.now(),{cache:'no-store'}),d=await r.json();if(!r.ok||!d.success)throw Error(d.message||'History gagal');draw(d)}catch(e){$('chartMsg').textContent=e.message;draw({})}}refresh();history();setInterval(refresh,10000);setInterval(history,10000);</script></body></html>